 const make=(role,id)=>{const c=mkCoach(role);c.id=id;c.age=42;staffCt(c,3,G.year);return c;};
 const a=make('pc','testC1'),a2=make('bc','testC1b'),a3=make('dc','testC1c');G.coach[G.user].pc=a;G.coach[G.user].bc=a2;G.coach[G.user].dc=a3;
 assert.equal(coachStudySend(a.id,'dom','yng'),'');assert.notEqual(coachStudySend(a2.id,'dom','yng'),'','동시 한 명');G.day=G.sis.ct.to;sisCoachBack();assert.notEqual(coachStudySend(a.id,'dom','yng'),'','코치 개인 연 1회');assert.equal(coachStudySend(a2.id,'dom','yng'),'','원 구단은 연 2명 지원');const returnA=G.sis.ct.to;assert.equal(G.hoL[fyNow()+':6'].exp['코치 교육·연수'],20);
